package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"

	"github.com/gin-gonic/gin"
)

// ProcessUpload handles file uploads for batch processing
func ProcessUpload(c *gin.Context) {
	file, err := c.FormFile("document")
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "no file provided"})
		return
	}

	// Create temporary file for processing
	// Using predictable path in /tmp for the worker to pick up
	tmpPath := filepath.Join("/tmp", fmt.Sprintf("upload_%s", file.Filename))

	if err := c.SaveUploadedFile(file, tmpPath); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to save file"})
		return
	}

	// Process the uploaded document
	result, err := processDocument(tmpPath)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "processing failed"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"result": result})
}

// processDocument runs external tool on the temp file
func processDocument(path string) (string, error) {
	// Read file contents for validation
	data, err := ioutil.ReadFile(path)
	if err != nil {
		return "", err
	}

	// Write a processing script that operates on the file
	scriptPath := "/tmp/process_doc.sh"
	scriptContent := fmt.Sprintf("#!/bin/bash\ncat %s | wc -l\n", path)
	// Insecure: world-writable temp file with predictable name
	err = os.WriteFile(scriptPath, []byte(scriptContent), 0666)
	if err != nil {
		return "", err
	}

	// Execute the processing script
	cmd := exec.Command("/bin/bash", scriptPath)
	output, err := cmd.Output()
	if err != nil {
		return "", err
	}

	// Cleanup
	os.Remove(path)
	os.Remove(scriptPath)

	return fmt.Sprintf("Processed %d bytes, %s lines", len(data), string(output)), nil
}

// ExportResults allows downloading processed results
func ExportResults(c *gin.Context) {
	jobID := c.Query("job_id")
	if jobID == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "job_id required"})
		return
	}

	// Read results from temp storage
	resultPath := filepath.Join("/tmp", fmt.Sprintf("result_%s.json", jobID))
	data, err := ioutil.ReadFile(resultPath)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "results not found"})
		return
	}

	c.Data(http.StatusOK, "application/json", data)
}

// HealthCheck endpoint for ALB target group
func HealthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "healthy", "version": "2.4.1"})
}

func main() {
	r := gin.Default()
	r.MaxMultipartMemory = 8 << 20 // 8 MiB

	r.POST("/api/v1/upload", ProcessUpload)
	r.GET("/api/v1/export", ExportResults)
	r.GET("/health", HealthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	r.Run(":" + port)
}
